function f_getMax (record of integer p_data) return integer {
     var integer v_len := lengthof(p_data), v_result;
    if (v_len > 0) {
       v_result := p_data[0];
     }
     for (var integer i := 1; i < v_len; i := i + 1) {
      if (p_data[i] > v_result) {
        v_result := p_data[i];
      }
    }
     return v_result;
  }

