// The template 
  template MyMessageType mw_myTemplate (template integer p_myFormalParam):=
  { field1 := p_myFormalParam,
     field2 := pattern "abc*xyz",
     field3 := true
  }
  // could be used as follows 
  pco1.receive(mw_myTemplate(?));
  // or as follows
  pco1.receive(mw_myTemplate(omit)); // provided that field1 is declared in MyMessageType as
                    // optional

// The template 
  template MyMessageType mw_myTemplate1 (template ( omit ) integer p_myFormalParam):=
  { field1 := p_myFormalParam,
     field2 := pattern "abc*xyz",
     field3 := true
  }
  // could be used as follows 
  pco1.receive(mw_myTemplate1(omit));
  // but not as follows
  pco1.receive(mw_myTemplate1(?)); // AnyValue is not within the restriction
  // the same template can be written shorter as
  template MyMessageType mw_myTemplate2 (omit integer p_myFormalParam):=
  { field1 := p_myFormalParam,
     field2 := pattern "abc*xyz",
     field3 := true
  }

